def verificar_ejercicio_4():
    necesarias = ["cantidad_salas", "rondas_por_sala", "rondas_normales", "rondas_revancha",
                  "suma_salas_verificador", "suma_rondas_verificador", "primera_ronda_es_normal"]
    faltantes = [v for v in necesarias if v not in globals()]
    if faltantes:
        print("⬜ Todavía te falta definir:", ", ".join(faltantes))
        return
    esperado_normales, esperado_revancha = 0, 0
    esperado_suma_salas, esperado_suma_rondas = 0, 0
    for sala in range(1, cantidad_salas + 1):
        for ronda in range(1, rondas_por_sala + 1):
            esperado_suma_salas = esperado_suma_salas + sala
            esperado_suma_rondas = esperado_suma_rondas + ronda
            if (sala + ronda) % 2 == 0:
                esperado_normales = esperado_normales + 1
            else:
                esperado_revancha = esperado_revancha + 1
    chequeos = [
        ("Cantidad de rondas normales", rondas_normales, esperado_normales),
        ("Cantidad de rondas de revancha", rondas_revancha, esperado_revancha),
        ("Suma de los números de sala recorridos", suma_salas_verificador, esperado_suma_salas),
        ("Suma de los números de ronda recorridos", suma_rondas_verificador, esperado_suma_rondas),
        ("Total de rondas (normales + revancha)", rondas_normales + rondas_revancha, esperado_normales + esperado_revancha),
        ("La Sala 1, Ronda 1 es normal", primera_ronda_es_normal, True),
    ]
    correctos = 0
    for nombre, obtenido, esperado in chequeos:
        if obtenido == esperado:
            print("✅", nombre, "está bien.")
            correctos += 1
        else:
            print("❌", nombre, "no calza. Tu programa dio", obtenido, "y se esperaba", esperado)
    print()
    print(correctos, "de", len(chequeos), "chequeos correctos.")

